ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    data: {
        schema: payload.data.schema default null,
        payload: payload.data.payload default {},
        event: {
            replayId: payload.data.event.replayId default null
        }
    },
    channel:
        payload.channel
            default p("cdc.streamingChannel")
}

logger.message:
#[write({
                    event: "CONTACT_ONBOARDING_PROCESSING_STARTED",
                    correlationId: vars.correlationId default "NOT_AVAILABLE",
                    contactId: vars.contactId default "UNKNOWN",
                    replayId: vars.replayId default "NOT_AVAILABLE"
                }, "application/json")]
